<script setup>import * as Vue from 'vue';import {component} from '../../../../rancher-common-ui/client/index.mjs';import {redactSecrets} from '../config/snapshot-secrets.mjs';import {compareSnapshotStates} from '../config/snapshot-diff';const props=defineProps({current:Object,saved:Object});const Shared=component('SnapshotComparison',Vue);const diff=Vue.computed(()=>compareSnapshotStates(props.current,props.saved));const format=value=>value===undefined?'Not Present':JSON.stringify(redactSecrets(value),null,2);</script><template><Shared :diff="diff" :format="format"/></template>
